func (s *Service) Terminate(ctx context.Context, serviceName string) (string, error) {
	return ovh.Call[string](ctx, s.c, &ovh.Request{Method: http.MethodPost, Path: ovh.Path("/v1/dedicated/nasha/{serviceName}/terminate", "serviceName", serviceName)})
}

// UpdateNasha calls PUT /v1/dedicated/nasha/{serviceName}: Alter this object properties
//
// Arguments:
//   - serviceName: The internal name of your storage
//   - body: the request body
//
// Requires the IAM action nasHA:apiovh:put.
func (s *Service) UpdateNasha(ctx context.Context, serviceName string, body DedicatedNashaStorage) error {
	return s.c.Do(ctx, &ovh.Request{Method: http.MethodPut, Path: ovh.Path("/v1/dedicated/nasha/{serviceName}", "serviceName", serviceName), Body: body}, nil)
}

// UpdatePartition calls PUT /v1/dedicated/nasha/{serviceName}/partition/{partitionName}: Alter this object properties
//
// Arguments:
//   - serviceName: The internal name of your storage
//   - partitionName: the given name of partition
//   - body: the request body
//
// Requires the IAM action nasHA:apiovh:partition/edit.
func (s *Service) UpdatePartition(ctx context.Context, serviceName string, partitionName string, body DedicatedNashaPartition) error {
	return s.c.Do(ctx, &ovh.Request{Method: http.MethodPut, Path: ovh.Path("/v1/dedicated/nasha/{serviceName}/partition/{partitionName}", "serviceName", serviceName, "partitionName", partitionName), Body: body}, nil)
}

// UpdateServiceInfos calls PUT /v1/dedicated/nasha/{serviceName}/serviceInfos: Update service information
//
// Updates the renewal settings of the service: automatic renewal, period, or deletion at
// expiration.
//
// Arguments:
//   - serviceName: The internal name of your storage
//   - body: the request body
//
// Requires the IAM action nasHA:apiovh:serviceInfos/edit.
func (s *Service) UpdateServiceInfos(ctx context.Context, serviceName string, body ServicesService) error {
	return s.c.Do(ctx, &ovh.Request{Method: http.MethodPut, Path: ovh.Path("/v1/dedicated/nasha/{serviceName}/serviceInfos", "serviceName", serviceName), Body: body}, nil)
}
